import asyncio
async def main():
    start = await yuki_workspace_read({"path":"/workspace/start.txt"})
    path = start["data"]["text"].strip()
    chain=[]
    seen=set()
    while True:
        if path in seen:
            return ("LOOP", chain)
        seen.add(path)
        r = await yuki_workspace_read({"path":"/workspace/"+ (path if path.startswith("nodes") else path)})
        txt = r["data"]["text"]
        d={}
        for line in txt.strip().splitlines():
            if "=" in line:
                k,v=line.split("=",1); d[k.strip()]=v.strip()
        val=d.get("value"); l=d.get("left"); rt=d.get("right")
        chain.append((path,val,d.get("name"),l,rt))
        if val is None:
            break
        if val=="END" or path=="END":
            break
        try:
            n=int(val)
        except:
            break
        nxt = l if n%2==0 else rt
        if nxt is None or nxt.upper()=="END":
            path="END"
            break
        path=nxt
    return chain
print(asyncio.run(main()))
